-- =====================================================================
-- Züccaciye KDS - veritabanı SON HALİ (28 Kasım 2026)
-- `proje` veritabanını seçip İçe Aktar ile yükleyin. Var olan tabloları,
-- view'ları, procedure'ları silip yeniden oluşturur (önce yedek alın).
--
-- STOK KURALI:
--   + giris, iade      - satis, takim_bozma, fire
--   fire_nedeni = 'takim_bozma' olan fire satırı stoğu ETKİLEMEZ (parça kaybı kaydı)
--   iptal_tarihi dolu olan satırlar hiç sayılmaz
-- =====================================================================

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
SET FOREIGN_KEY_CHECKS = 0;
SET NAMES utf8mb4;
START TRANSACTION;

-- Eski view'lar (önceki güncellemeden kalmış olabilecekler dahil)
DROP VIEW IF EXISTS `v_yavas_satanlar`, `v_kategori_karlilik`, `v_urun_performans`, `v_gunluk_ciro`,
  `v_iade_tutarlari`, `v_bugun_fiyati_degisenler`, `v_saat_yogunlugu`, `v_eksik_teslimatlar`,
  `v_fire_raporu`, `v_kritik_stok`, `v_geciken_siparisler`, `v_bekleyen_talepler`;

