DROP TABLE IF EXISTS `urunler`;
CREATE TABLE `urunler` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `barkod` varchar(32) COLLATE utf8mb4_turkish_ci NOT NULL,
  `marka_id` int UNSIGNED NOT NULL,
  `kategori_id` int UNSIGNED NOT NULL,
  `urun_adi` varchar(150) COLLATE utf8mb4_turkish_ci NOT NULL,
  `varyant` varchar(100) COLLATE utf8mb4_turkish_ci DEFAULT NULL,
  `paket_adedi` int UNSIGNED NOT NULL DEFAULT '1',
  `alis_fiyati` decimal(10,2) NOT NULL DEFAULT '0.00',
  `satis_fiyati` decimal(10,2) NOT NULL DEFAULT '0.00',
  `stok_miktari` int NOT NULL DEFAULT '0',
  `kritik_stok_seviyesi` int UNSIGNED NOT NULL DEFAULT '2',
  `hedef_stok` int UNSIGNED NOT NULL DEFAULT '0',
  `aktif` tinyint(1) NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_barkod` (`barkod`),
  KEY `ix_urun_kategori` (`kategori_id`),
  KEY `ix_urun_marka` (`marka_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

