--
-- Tablo yapısı `satislar`
--

DROP TABLE IF EXISTS `satislar`;
CREATE TABLE `satislar` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `kullanici_id` int UNSIGNED NOT NULL,
  `tarih` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `toplam_tutar` decimal(10,2) NOT NULL DEFAULT '0.00',
  `odeme_tipi` enum('nakit','kart') COLLATE utf8mb4_turkish_ci NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_satis_tarih` (`tarih`),
  KEY `fk_satis_kullanici` (`kullanici_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

