--
-- Tablo yapısı `satis_detay`
--

DROP TABLE IF EXISTS `satis_detay`;
CREATE TABLE `satis_detay` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `satis_id` int UNSIGNED NOT NULL,
  `urun_id` int UNSIGNED NOT NULL,
  `adet` int UNSIGNED NOT NULL,
  `birim_fiyat` decimal(10,2) NOT NULL,
  `alis_fiyati` decimal(10,2) NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_sd_urun` (`urun_id`),
  KEY `fk_sd_satis` (`satis_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

