--
-- Tablo yapısı `siparisler`
--

DROP TABLE IF EXISTS `siparisler`;
CREATE TABLE `siparisler` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `kullanici_id` int UNSIGNED NOT NULL,
  `olusturma_tarihi` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `verilme_tarihi` datetime DEFAULT NULL,
  `teslim_tarihi` datetime DEFAULT NULL,
  `durum` enum('taslak','verildi','teslim_alindi') COLLATE utf8mb4_turkish_ci NOT NULL DEFAULT 'taslak',
  `aciklama` varchar(255) COLLATE utf8mb4_turkish_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_siparis_durum` (`durum`),
  KEY `fk_siparis_kullanici` (`kullanici_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

