-- --------------------------------------------------------
--
-- Tablo yapısı `stok_hareketleri`
--

DROP TABLE IF EXISTS `stok_hareketleri`;
CREATE TABLE `stok_hareketleri` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `urun_id` int UNSIGNED NOT NULL,
  `kullanici_id` int UNSIGNED NOT NULL,
  `tur` enum('giris','satis','iade','fire','takim_bozma') COLLATE utf8mb4_turkish_ci NOT NULL,
  `miktar` int UNSIGNED NOT NULL,
  `birim_maliyet` decimal(10,2) DEFAULT NULL,
  `fire_nedeni` enum('rafta_kirildi','kusurlu_iade','nakliye_hasari','takim_bozma','diger') COLLATE utf8mb4_turkish_ci DEFAULT NULL,
  `tarih` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `aciklama` varchar(255) COLLATE utf8mb4_turkish_ci DEFAULT NULL,
  `iptal_tarihi` datetime DEFAULT NULL,
  `satis_id` int UNSIGNED DEFAULT NULL,
  `siparis_id` int UNSIGNED DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_sh_urun_tarih` (`urun_id`,`tarih`),
  KEY `ix_sh_tur_tarih` (`tur`,`tarih`),
  KEY `ix_sh_satis` (`satis_id`),
  KEY `ix_sh_siparis` (`siparis_id`),
  KEY `fk_sh_kullanici` (`kullanici_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

