DROP TABLE IF EXISTS `urun_talepleri`;
CREATE TABLE `urun_talepleri` (
  `id` int UNSIGNED NOT NULL AUTO_INCREMENT,
  `musteri_id` int UNSIGNED NOT NULL,
  `urun_id` int UNSIGNED NOT NULL,
  `kullanici_id` int UNSIGNED NOT NULL,
  `adet` int UNSIGNED NOT NULL DEFAULT '1',
  `talep_tarihi` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `durum` enum('bekliyor','bildirildi','tamamlandi','iptal') COLLATE utf8mb4_turkish_ci NOT NULL DEFAULT 'bekliyor',
  `bildirim_tarihi` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `ix_talep_durum` (`durum`),
  KEY `ix_talep_urun` (`urun_id`),
  KEY `fk_talep_musteri` (`musteri_id`),
  KEY `fk_talep_kullanici` (`kullanici_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_turkish_ci;

