--
-- Tetikleyici: maliyet ve fire nedeni boşsa doldur
--
DROP TRIGGER IF EXISTS `trg_sh_birim_maliyet`;
DELIMITER $$
CREATE TRIGGER `trg_sh_birim_maliyet` BEFORE INSERT ON `stok_hareketleri` FOR EACH ROW BEGIN
  IF NEW.birim_maliyet IS NULL AND NEW.tur IN ('giris','fire','takim_bozma') THEN
    SET NEW.birim_maliyet = (SELECT alis_fiyati FROM urunler WHERE id = NEW.urun_id);
  END IF;
  IF NEW.tur = 'fire' AND NEW.fire_nedeni IS NULL THEN
    SET NEW.fire_nedeni = 'diger';
  END IF;
END
$$
DELIMITER ;

--
-- Yordamlar (takım bozma)
--
DELIMITER $$
DROP PROCEDURE IF EXISTS `sp_parca_stoga_ekle`$$
CREATE PROCEDURE `sp_parca_stoga_ekle` (IN `p_takim_id` INT UNSIGNED, IN `p_kullanici_id` INT UNSIGNED, IN `p_marka` INT UNSIGNED, IN `p_kategori` INT UNSIGNED, IN `p_ad` VARCHAR(150), IN `p_adet` INT UNSIGNED, IN `p_fiyat` DECIMAL(10,2), IN `p_maliyet` DECIMAL(10,2))   BEGIN
  DECLARE v_id  INT UNSIGNED DEFAULT NULL;
  DECLARE v_kat INT UNSIGNED DEFAULT NULL;

  -- Parçanın adına göre kategori seç
  IF p_ad LIKE '%tabak%' OR p_ad LIKE '%tabağ%' THEN
    SELECT id INTO v_kat FROM kategoriler WHERE ad = 'Tabak' LIMIT 1;
  ELSEIF p_ad LIKE '%bardak%' OR p_ad LIKE '%bardağ%' THEN
    SELECT id INTO v_kat FROM kategoriler WHERE ad = 'Bardak' LIMIT 1;
  ELSEIF p_ad LIKE '%fincan%' THEN
    SELECT id INTO v_kat FROM kategoriler WHERE ad = 'Fincan' LIMIT 1;
  END IF;
  SET v_kat = IFNULL(v_kat, p_kategori);   -- bulunamazsa takımın kategorisi

  SELECT id INTO v_id
  FROM urunler
  WHERE urun_adi = p_ad AND marka_id = p_marka AND paket_adedi = 1
  LIMIT 1;

  IF v_id IS NULL THEN
    INSERT INTO urunler (barkod, marka_id, kategori_id, urun_adi, varyant, paket_adedi,
                         alis_fiyati, satis_fiyati, stok_miktari,
                         kritik_stok_seviyesi, hedef_stok, aktif)
    VALUES (CONCAT('TP-', p_takim_id, '-', UPPER(LEFT(MD5(p_ad), 6))),
            p_marka, v_kat, p_ad, 'tekli', 1,
            p_maliyet, p_fiyat, 0,
            0, 0, 1);
    SET v_id = LAST_INSERT_ID();
  END IF;

  INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, aciklama)
  VALUES (v_id, p_kullanici_id, 'giris', p_adet, p_maliyet,
          CONCAT('Takım parçalamadan (ürün #', p_takim_id, ')'));

  UPDATE urunler SET stok_miktari = stok_miktari + p_adet WHERE id = v_id;
END$$

DROP PROCEDURE IF EXISTS `sp_takim_boz`$$
CREATE PROCEDURE `sp_takim_boz` (IN `p_takim_id` INT UNSIGNED, IN `p_kullanici_id` INT UNSIGNED, IN `p_kalan_parca` INT UNSIGNED, IN `p_yeni_varyant` VARCHAR(100), IN `p_satis_fiyati` DECIMAL(10,2), IN `p_fire_nedeni` VARCHAR(20), IN `p_aciklama` VARCHAR(200))   BEGIN
  DECLARE v_ad        VARCHAR(150);
  DECLARE v_marka     INT UNSIGNED;
  DECLARE v_kategori  INT UNSIGNED;
  DECLARE v_paket     INT UNSIGNED;
  DECLARE v_alis      DECIMAL(10,2);
  DECLARE v_stok      INT;
  DECLARE v_parca_mal DECIMAL(10,2);
  DECLARE v_fire_adet INT UNSIGNED;
  DECLARE v_yeni_id   INT UNSIGNED;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  START TRANSACTION;

  SELECT urun_adi, marka_id, kategori_id, paket_adedi, alis_fiyati, stok_miktari
    INTO v_ad, v_marka, v_kategori, v_paket, v_alis, v_stok
  FROM urunler WHERE id = p_takim_id FOR UPDATE;

  IF v_ad IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ürün bulunamadı';
  END IF;
  IF v_paket < 2 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Bu ürün takım değil (paket_adedi < 2)';
  END IF;
  IF v_stok < 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stokta bozulacak takım yok';
  END IF;
  IF p_kalan_parca >= v_paket THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Kalan parça sayısı paket adedinden az olmalı';
  END IF;

  SET v_parca_mal = ROUND(v_alis / v_paket, 2);
  SET v_fire_adet = v_paket - p_kalan_parca;

  -- a) Takım stoktan çıkar
  INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, aciklama)
  VALUES (p_takim_id, p_kullanici_id, 'takim_bozma', 1, v_alis,
          CONCAT('Takım bozuldu. ', IFNULL(p_aciklama, '')));

  UPDATE urunler SET stok_miktari = stok_miktari - 1 WHERE id = p_takim_id;

  -- b) Kırık/artık parçaların kaybı (miktar = PARÇA sayısı; stoktan ayrıca düşülmez)
  --    fire_nedeni her zaman 'takim_bozma'; asıl neden açıklamaya yazılır
  INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, fire_nedeni, aciklama)
  VALUES (p_takim_id, p_kullanici_id, 'fire', v_fire_adet, v_parca_mal,
          'takim_bozma',   -- parça firesi: stok hesabına girmez, sadece kayıp
          CONCAT('Takımdan ', v_fire_adet, ' parça fire (', IFNULL(p_fire_nedeni, 'diger'), '). ', IFNULL(p_aciklama, '')));

  -- c) Sağlam parçalar: varsa mevcut "eksik" ürüne ekle, yoksa yeni ürün aç
  IF p_kalan_parca > 0 THEN
    SELECT id INTO v_yeni_id
    FROM urunler
    WHERE urun_adi = CONCAT(v_ad, ' (eksik)')
      AND marka_id = v_marka
      AND paket_adedi = p_kalan_parca
      AND (varyant <=> p_yeni_varyant)
    LIMIT 1;

    IF v_yeni_id IS NULL THEN
      INSERT INTO urunler (barkod, marka_id, kategori_id, urun_adi, varyant, paket_adedi,
                           alis_fiyati, satis_fiyati, stok_miktari,
                           kritik_stok_seviyesi, hedef_stok, aktif)
      VALUES (CONCAT('TB-', p_takim_id, '-', p_kalan_parca, '-', UNIX_TIMESTAMP()),
              v_marka, v_kategori, CONCAT(v_ad, ' (eksik)'), p_yeni_varyant, p_kalan_parca,
              v_parca_mal * p_kalan_parca, p_satis_fiyati, 0,
              0, 0, 1);   -- kritik/hedef 0: tekrar sipariş edilmez
      SET v_yeni_id = LAST_INSERT_ID();
    END IF;

    INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, aciklama)
    VALUES (v_yeni_id, p_kullanici_id, 'giris', 1, v_parca_mal * p_kalan_parca,
            CONCAT('Takım bozmadan (ürün #', p_takim_id, ')'));

    UPDATE urunler SET stok_miktari = stok_miktari + 1 WHERE id = v_yeni_id;
  END IF;

  COMMIT;

  SELECT v_yeni_id AS yeni_urun_id, v_fire_adet AS fire_parca,
         v_parca_mal * v_fire_adet AS fire_kaybi_tl;
END$$

DROP PROCEDURE IF EXISTS `sp_takim_parcala`$$
CREATE PROCEDURE `sp_takim_parcala` (IN `p_takim_id` INT UNSIGNED, IN `p_kullanici_id` INT UNSIGNED, IN `p_parca1_adi` VARCHAR(150), IN `p_parca1_adet` INT UNSIGNED, IN `p_parca1_fiyat` DECIMAL(10,2), IN `p_parca2_adi` VARCHAR(150), IN `p_parca2_adet` INT UNSIGNED, IN `p_parca2_fiyat` DECIMAL(10,2), IN `p_fire_nedeni` VARCHAR(20), IN `p_aciklama` VARCHAR(200))   BEGIN
  DECLARE v_ad        VARCHAR(150);
  DECLARE v_marka     INT UNSIGNED;
  DECLARE v_kategori  INT UNSIGNED;
  DECLARE v_paket     INT UNSIGNED;
  DECLARE v_alis      DECIMAL(10,2);
  DECLARE v_stok      INT;
  DECLARE v_parca_mal DECIMAL(10,2);
  DECLARE v_kalan     INT UNSIGNED;
  DECLARE v_fire_adet INT UNSIGNED;

  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    RESIGNAL;
  END;

  SET p_parca1_adet = IFNULL(p_parca1_adet, 0);
  SET p_parca2_adet = IFNULL(p_parca2_adet, 0);

  START TRANSACTION;

  SELECT urun_adi, marka_id, kategori_id, paket_adedi, alis_fiyati, stok_miktari
    INTO v_ad, v_marka, v_kategori, v_paket, v_alis, v_stok
  FROM urunler WHERE id = p_takim_id FOR UPDATE;

  IF v_ad IS NULL THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Ürün bulunamadı';
  END IF;
  IF v_paket < 2 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Bu ürün takım değil (paket_adedi < 2)';
  END IF;
  IF v_stok < 1 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Stokta parçalanacak takım yok';
  END IF;

  SET v_kalan = p_parca1_adet + p_parca2_adet;
  IF v_kalan >= v_paket THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Sağlam parça sayısı paket adedinden az olmalı';
  END IF;

  SET v_parca_mal = ROUND(v_alis / v_paket, 2);
  SET v_fire_adet = v_paket - v_kalan;

  -- a) Takım stoktan çıkar
  INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, aciklama)
  VALUES (p_takim_id, p_kullanici_id, 'takim_bozma', 1, v_alis,
          CONCAT('Takım parçalandı. ', IFNULL(p_aciklama, '')));

  UPDATE urunler SET stok_miktari = stok_miktari - 1 WHERE id = p_takim_id;

  -- b) Kırık parçaların kaybı (miktar = PARÇA sayısı; stoktan ayrıca düşülmez)
  --    fire_nedeni her zaman 'takim_bozma'; asıl neden açıklamaya yazılır
  INSERT INTO stok_hareketleri (urun_id, kullanici_id, tur, miktar, birim_maliyet, fire_nedeni, aciklama)
  VALUES (p_takim_id, p_kullanici_id, 'fire', v_fire_adet, v_parca_mal,
          'takim_bozma',   -- parça firesi: stok hesabına girmez, sadece kayıp
          CONCAT('Takımdan ', v_fire_adet, ' parça fire (', IFNULL(p_fire_nedeni, 'diger'), '). ', IFNULL(p_aciklama, '')));

  -- c) Sağlam parçalar tekli ürün olarak stoğa
  IF p_parca1_adet > 0 THEN
    CALL sp_parca_stoga_ekle(p_takim_id, p_kullanici_id, v_marka, v_kategori,
                             p_parca1_adi, p_parca1_adet, p_parca1_fiyat, v_parca_mal);
  END IF;
  IF p_parca2_adet > 0 THEN
    CALL sp_parca_stoga_ekle(p_takim_id, p_kullanici_id, v_marka, v_kategori,
                             p_parca2_adi, p_parca2_adet, p_parca2_fiyat, v_parca_mal);
  END IF;

  COMMIT;

  SELECT v_fire_adet AS fire_parca,
         v_parca_mal * v_fire_adet AS fire_kaybi_tl,
         v_kalan AS stoga_alinan_parca;
END$$

DELIMITER ;

-- --------------------------------------------------------
--
-- View'lar (DEFINER'sız)
--

CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_bekleyen_talepler` AS
SELECT t.id, t.talep_tarihi, t.adet, t.durum, mu.ad_soyad, mu.telefon,
       u.id AS urun_id, u.urun_adi, u.varyant, u.stok_miktari
FROM urun_talepleri t
JOIN musteriler mu ON mu.id = t.musteri_id
JOIN urunler    u  ON u.id  = t.urun_id
WHERE t.durum IN ('bekliyor','bildirildi');

CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_geciken_siparisler` AS
SELECT s.id, s.verilme_tarihi, TO_DAYS(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00')) - TO_DAYS(s.verilme_tarihi) AS gecen_gun
FROM siparisler s
WHERE s.durum = 'verildi' AND s.verilme_tarihi < CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00') - INTERVAL 5 DAY;

-- Kritik stok: taslak/verilmiş siparişlerde yolda olan adet öneriden düşülür.
-- onerilen_siparis = 0 ise ürün zaten siparişte demektir.
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_kritik_stok` AS
SELECT u.id, u.barkod, m.ad AS marka, k.ad AS kategori, u.urun_adi, u.varyant,
       u.stok_miktari, u.kritik_stok_seviyesi, u.hedef_stok,
       COALESCE(y.yoldaki, 0) AS yoldaki_adet,
       GREATEST(CAST(u.hedef_stok AS SIGNED) - u.stok_miktari - COALESCE(y.yoldaki, 0), 0) AS onerilen_siparis
FROM urunler u
JOIN markalar    m ON m.id = u.marka_id
JOIN kategoriler k ON k.id = u.kategori_id
LEFT JOIN (
    SELECT sd.urun_id,
           SUM(CASE WHEN s.durum = 'verildi' THEN CAST(sd.adet AS SIGNED) - sd.gelen_adet
                    ELSE sd.adet END) AS yoldaki
    FROM siparis_detay sd JOIN siparisler s ON s.id = sd.siparis_id
    WHERE s.durum IN ('taslak','verildi')
    GROUP BY sd.urun_id
) y ON y.urun_id = u.id
WHERE u.aktif = 1 AND u.hedef_stok > 0 AND u.stok_miktari <= u.kritik_stok_seviyesi;

-- 6.0 Fire raporu: iptal bilgisi ve parça firesi ayrımı eklendi
--     (yönetici iptal edilenleri de görür; geri al butonu iptal_tarihi NULL
--      ve fire_nedeni <> 'takim_bozma' olan satırlarda gösterilir)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_fire_raporu` AS
SELECT sh.id, sh.tarih, u.id AS urun_id, u.urun_adi, u.varyant,
       k.ad AS kategori, m.ad AS marka,
       sh.miktar, sh.birim_maliyet, sh.miktar * sh.birim_maliyet AS kayip_tl,
       sh.fire_nedeni, sh.aciklama, ku.ad_soyad AS kaydeden,
       sh.iptal_tarihi,
       (sh.iptal_tarihi IS NULL AND sh.fire_nedeni <> 'takim_bozma') AS geri_alinabilir
FROM stok_hareketleri sh
JOIN urunler      u  ON u.id  = sh.urun_id
JOIN kategoriler  k  ON k.id  = u.kategori_id
JOIN markalar     m  ON m.id  = u.marka_id
JOIN kullanicilar ku ON ku.id = sh.kullanici_id
WHERE sh.tur = 'fire';

-- 6.1 Yardımcı: her iadenin tutarı ve kâra etkisi (satış anındaki fiyatla)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_iade_tutarlari` AS
SELECT h.id AS hareket_id, h.tarih, h.urun_id, h.satis_id, h.miktar,
       h.miktar * d.birim_fiyat                   AS tutar,
       h.miktar * (d.birim_fiyat - d.alis_fiyati) AS kar
FROM stok_hareketleri h
JOIN satis_detay d ON d.satis_id = h.satis_id AND d.urun_id = h.urun_id
WHERE h.tur = 'iade' AND h.iptal_tarihi IS NULL;

-- 6.2 Bugün fiyatı değişenler (etiket güncelleme listesi)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_bugun_fiyati_degisenler` AS
SELECT f.id, f.tarih, u.id AS urun_id, u.barkod, m.ad AS marka,
       u.urun_adi, u.varyant, f.eski_fiyat, f.yeni_fiyat
FROM fiyat_gecmisi f
JOIN urunler  u ON u.id = f.urun_id
JOIN markalar m ON m.id = u.marka_id
WHERE f.tarih >= DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00')) AND f.tarih < DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00')) + INTERVAL 1 DAY;

-- 6.3 Günlük ciro: brüt, iade, net ciro ve net kâr (fire kaybı düşülmüş)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_gunluk_ciro` AS
SELECT gun,
       SUM(satis_sayisi)                           AS satis_sayisi,
       SUM(brut_ciro)                              AS brut_ciro,
       SUM(nakit)                                  AS nakit,
       SUM(kart)                                   AS kart,
       SUM(iade_tutari)                            AS iade_tutari,
       SUM(brut_ciro) - SUM(iade_tutari)           AS net_ciro,
       SUM(fire_kaybi)                             AS fire_kaybi,
       SUM(kar) - SUM(iade_kar) - SUM(fire_kaybi)  AS net_kar
FROM (
    SELECT DATE(s.tarih) AS gun, 1 AS satis_sayisi, s.toplam_tutar AS brut_ciro,
           CASE WHEN s.odeme_tipi = 'nakit' THEN s.toplam_tutar ELSE 0 END AS nakit,
           CASE WHEN s.odeme_tipi = 'kart'  THEN s.toplam_tutar ELSE 0 END AS kart,
           (SELECT SUM(d.adet * (d.birim_fiyat - d.alis_fiyati))
              FROM satis_detay d WHERE d.satis_id = s.id) AS kar,
           0 AS iade_tutari, 0 AS iade_kar, 0 AS fire_kaybi
    FROM satislar s
    UNION ALL
    SELECT DATE(i.tarih), 0, 0, 0, 0, 0, i.tutar, i.kar, 0
    FROM v_iade_tutarlari i
    UNION ALL
    SELECT DATE(h.tarih), 0, 0, 0, 0, 0, 0, 0, h.miktar * h.birim_maliyet
    FROM stok_hareketleri h
    WHERE h.tur = 'fire' AND h.iptal_tarihi IS NULL
) x
GROUP BY gun;

-- 6.4 Ürün performansı (diğer KDS view'larının temeli)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_urun_performans` AS
SELECT u.id AS urun_id, u.barkod, m.ad AS marka, k.ad AS kategori,
       u.urun_adi, u.varyant, u.aktif,
       u.alis_fiyati, u.satis_fiyati, u.stok_miktari,
       u.stok_miktari * u.alis_fiyati                 AS stoktaki_sermaye,
       COALESCE(sd.adet, 0)                           AS toplam_satilan,
       COALESCE(sd.adet_30, 0)                        AS son_30_gun_satilan,
       sd.son_satis                                   AS son_satis_tarihi,
       DATEDIFF(DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00')), sd.son_satis)              AS son_satistan_beri_gun,
       COALESCE(sd.ciro, 0)                           AS brut_ciro,
       COALESCE(ia.tutar, 0)                          AS iade_tutari,
       COALESCE(sd.ciro, 0) - COALESCE(ia.tutar, 0)   AS net_ciro,
       COALESCE(fi.kayip, 0)                          AS fire_kaybi,
       COALESCE(sd.kar, 0) - COALESCE(ia.kar, 0) - COALESCE(fi.kayip, 0) AS net_kar
FROM urunler u
JOIN markalar    m ON m.id = u.marka_id
JOIN kategoriler k ON k.id = u.kategori_id
LEFT JOIN (
    SELECT d.urun_id,
           SUM(d.adet)                                    AS adet,
           SUM(CASE WHEN s.tarih >= DATE(CONVERT_TZ(UTC_TIMESTAMP(), '+00:00', '+03:00')) - INTERVAL 30 DAY THEN d.adet ELSE 0 END) AS adet_30,
           MAX(s.tarih)                                   AS son_satis,
           SUM(d.adet * d.birim_fiyat)                    AS ciro,
           SUM(d.adet * (d.birim_fiyat - d.alis_fiyati))  AS kar
    FROM satis_detay d JOIN satislar s ON s.id = d.satis_id
    GROUP BY d.urun_id
) sd ON sd.urun_id = u.id
LEFT JOIN (
    SELECT urun_id, SUM(tutar) AS tutar, SUM(kar) AS kar
    FROM v_iade_tutarlari GROUP BY urun_id
) ia ON ia.urun_id = u.id
LEFT JOIN (
    SELECT urun_id, SUM(miktar * birim_maliyet) AS kayip
    FROM stok_hareketleri WHERE tur = 'fire' AND iptal_tarihi IS NULL
    GROUP BY urun_id
) fi ON fi.urun_id = u.id;

-- 6.5 Yavaş satanlar: son 30 günde hiç satılmamış, stokta duran ürünler.
--     Rafta en çok parası bağlı olan üstte (indirim/kampanya adayları).
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_yavas_satanlar` AS
SELECT urun_id, barkod, marka, kategori, urun_adi, varyant,
       stok_miktari, satis_fiyati, stoktaki_sermaye,
       toplam_satilan, son_satis_tarihi, son_satistan_beri_gun,
       CASE WHEN toplam_satilan = 0 THEN 'Hiç satılmadı'
            ELSE '30 gündür satış yok' END AS durum
FROM v_urun_performans
WHERE aktif = 1 AND stok_miktari > 0 AND son_30_gun_satilan = 0
ORDER BY stoktaki_sermaye DESC;

-- 6.6 Kategori kârlılığı
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_kategori_karlilik` AS
SELECT kategori,
       COUNT(*)               AS urun_sayisi,
       SUM(toplam_satilan)    AS satilan_adet,
       SUM(net_ciro)          AS net_ciro,
       SUM(fire_kaybi)        AS fire_kaybi,
       SUM(net_kar)           AS net_kar,
       ROUND(100 * SUM(net_kar) / NULLIF(SUM(net_ciro), 0), 1) AS kar_marji_yuzde,
       SUM(stoktaki_sermaye)  AS stoktaki_sermaye
FROM v_urun_performans
GROUP BY kategori
ORDER BY net_kar DESC;

-- 6.7 Gün/saat yoğunluğu (personel ve kasa planlaması)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_saat_yogunlugu` AS
SELECT DAYOFWEEK(s.tarih) AS gun_no,
       ELT(DAYOFWEEK(s.tarih), 'Pazar','Pazartesi','Salı','Çarşamba','Perşembe','Cuma','Cumartesi') AS gun,
       HOUR(s.tarih)       AS saat,
       COUNT(*)            AS satis_sayisi,
       SUM(s.toplam_tutar) AS ciro
FROM satislar s
GROUP BY DAYOFWEEK(s.tarih), HOUR(s.tarih);

-- 6.8 Eksik teslim edilen sipariş satırları (tedarikçinin eksik getirdikleri)
CREATE OR REPLACE SQL SECURITY INVOKER VIEW `v_eksik_teslimatlar` AS
SELECT s.id AS siparis_id, s.teslim_tarihi, u.id AS urun_id, u.urun_adi, u.varyant,
       sd.adet AS siparis_adet, sd.gelen_adet, sd.adet - sd.gelen_adet AS eksik_adet
FROM siparis_detay sd
JOIN siparisler s ON s.id = sd.siparis_id
JOIN urunler    u ON u.id = sd.urun_id
WHERE s.durum = 'teslim_alindi' AND sd.gelen_adet < sd.adet;



-- --------------------------------------------------------
--
-- İlişkiler (foreign key)
--
ALTER TABLE `satislar`
  ADD CONSTRAINT `fk_satis_kullanici` FOREIGN KEY (`kullanici_id`) REFERENCES `kullanicilar` (`id`);
ALTER TABLE `satis_detay`
  ADD CONSTRAINT `fk_sd_satis` FOREIGN KEY (`satis_id`) REFERENCES `satislar` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `fk_sd_urun` FOREIGN KEY (`urun_id`) REFERENCES `urunler` (`id`);
ALTER TABLE `siparisler`
  ADD CONSTRAINT `fk_siparis_kullanici` FOREIGN KEY (`kullanici_id`) REFERENCES `kullanicilar` (`id`);
ALTER TABLE `siparis_detay`
  ADD CONSTRAINT `fk_spd_siparis` FOREIGN KEY (`siparis_id`) REFERENCES `siparisler` (`id`) ON DELETE CASCADE,
  ADD CONSTRAINT `fk_spd_urun` FOREIGN KEY (`urun_id`) REFERENCES `urunler` (`id`);
ALTER TABLE `stok_hareketleri`
  ADD CONSTRAINT `fk_sh_kullanici` FOREIGN KEY (`kullanici_id`) REFERENCES `kullanicilar` (`id`),
  ADD CONSTRAINT `fk_sh_satis` FOREIGN KEY (`satis_id`) REFERENCES `satislar` (`id`),
  ADD CONSTRAINT `fk_sh_siparis` FOREIGN KEY (`siparis_id`) REFERENCES `siparisler` (`id`),
  ADD CONSTRAINT `fk_sh_urun` FOREIGN KEY (`urun_id`) REFERENCES `urunler` (`id`);
ALTER TABLE `urunler`
  ADD CONSTRAINT `fk_urun_kategori` FOREIGN KEY (`kategori_id`) REFERENCES `kategoriler` (`id`) ON UPDATE CASCADE,
  ADD CONSTRAINT `fk_urun_marka` FOREIGN KEY (`marka_id`) REFERENCES `markalar` (`id`) ON UPDATE CASCADE;
ALTER TABLE `urun_talepleri`
  ADD CONSTRAINT `fk_talep_kullanici` FOREIGN KEY (`kullanici_id`) REFERENCES `kullanicilar` (`id`),
  ADD CONSTRAINT `fk_talep_musteri` FOREIGN KEY (`musteri_id`) REFERENCES `musteriler` (`id`),
  ADD CONSTRAINT `fk_talep_urun` FOREIGN KEY (`urun_id`) REFERENCES `urunler` (`id`);
ALTER TABLE `fiyat_gecmisi`
  ADD CONSTRAINT `fk_fg_urun` FOREIGN KEY (`urun_id`) REFERENCES `urunler` (`id`),
  ADD CONSTRAINT `fk_fg_kullanici` FOREIGN KEY (`kullanici_id`) REFERENCES `kullanicilar` (`id`);

COMMIT;
SET FOREIGN_KEY_CHECKS = 1;
